```apex
/**
 * Queueable job that creates a single CSAT survey Task for one Case.
 *
 * One job instance handles exactly one Case. This keeps every case's
 * survey-task creation fully isolated: a DML failure (e.g. a validation
 * rule blocking Task insert) for one case's job has no effect on any
 * other case's job, since each runs as its own independent asynchronous
 * execution.
 *
 * The job re-queries the Case (rather than trusting data passed in from
 * the trigger) because:
 *  - Queueable execution is asynchronous and may run after the
 *    triggering transaction commits, so we want the current, committed
 *    state of the record.
 *  - It keeps the constructor simple (just an Id, as specified) and
 *    avoids serializing/passing SObject state across the async boundary.
 *
 * Defensive checks (IsClosed still true, ContactId still populated) guard
 * against the case being reopened or losing its contact between the
 * trigger firing and the job executing.
 */
public with sharing class CaseSurveyJob implements Queueable {

    private final Id caseId;

    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
    }

    public void execute(QueueableContext context) {
        if (caseId == null) {
            return;
        }

        List<Case> cases = [
            SELECT Id, CaseNumber, ContactId, IsClosed
            FROM Case
            WHERE Id = :caseId
            LIMIT 1
        ];

        if (cases.isEmpty()) {
            return;
        }

        Case c = cases[0];

        // Defensive re-check: by the time this async job runs the case
        // could theoretically have been reopened or lost its contact.
        // Only create the survey task if conditions still hold.
        if (!c.IsClosed || c.ContactId == null) {
            return;
        }

        Task surveyTask = new Task(
            WhatId = c.Id,
            WhoId = c.ContactId,
            Subject = 'CSAT survey: ' + c.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status = 'Not Started'
        );

        insert surveyTask;
    }
}
```

