public class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // the matched or created contact
        public Id opportunityId;    // the created donation
        public String errorMessage; // NPSP's failure information when success is false

        public ImportResult() {
            this.success = false;
        }
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // Stage one npsp__DataImport__c per gift, preserving input order.
        List<npsp__DataImport__c> diRecords = new List<npsp__DataImport__c>();

        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c();
            di.npsp__Contact1_Firstname__c = gift.firstName;
            di.npsp__Contact1_Lastname__c = gift.lastName;
            di.npsp__Contact1_Personal_Email__c = gift.email;
            di.npsp__Donation_Amount__c = gift.amount;
            di.npsp__Donation_Date__c = gift.giftDate;
            di.npsp__Donation_Donor__c = 'Contact1';
            diRecords.add(di);
        }

        insert diRecords;

        // Use the org's configured Data Import settings (matching rules, etc.)
        npsp__Data_Import_Settings__c settings = npsp__Data_Import_Settings__c.getOrgDefaults();

        // Process synchronously, in this transaction, using NPSP's supported global Apex API
        // for Batch Data Import processing.
        npsp.BDI_DataImport_API.processDataImportRecords(
            settings,
            diRecords,
            false // isDryRun = false, perform the actual import
        );

        // Requery to get the fields NPSP wrote back (Status, imported lookups, failure info).
        Set<Id> diIds = new Set<Id>();
        for (npsp__DataImport__c di : diRecords) {
            diIds.add(di.Id);
        }

        Map<Id, npsp__DataImport__c> processedById = new Map<Id, npsp__DataImport__c>(
            [
                SELECT Id,
                       npsp__Status__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c,
                       npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :diIds
            ]
        );

        // Build results in the same order as the input gifts / staged records.
        for (npsp__DataImport__c staged : diRecords) {
            npsp__DataImport__c processed = processedById.get(staged.Id);
            ImportResult result = new ImportResult();

            if (processed != null) {
                Boolean imported = processed.npsp__Status__c == 'Imported';
                result.success = imported;
                result.contactId = processed.npsp__Contact1Imported__c;
                result.opportunityId = processed.npsp__DonationImported__c;
                result.errorMessage = processed.npsp__FailureInformation__c;
            } else {
                result.success = false;
                result.errorMessage = 'Data Import record could not be retrieved after processing.';
            }

            results.add(result);
        }

        return results;
    }
}
