```apex
public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final String MAJOR_GIFT_SUBJECT = 'Major gift thank-you call';
    private static final Decimal THRESHOLD_AMOUNT = 5000;

    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newlist,
        List<SObject> oldlist,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dmlWrapper = new npsp.TDTM_Runnable.DmlWrapper();

        if (newlist == null || newlist.isEmpty()) {
            return dmlWrapper;
        }

        if (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert
            && triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate) {
            return dmlWrapper;
        }

        List<Task> tasksToInsert = new List<Task>();

        for (Integer i = 0; i < newlist.size(); i++) {
            Opportunity newOpp = (Opportunity) newlist[i];

            Boolean newQualifies = newOpp.IsWon == true
                && newOpp.Amount != null
                && newOpp.Amount >= THRESHOLD_AMOUNT;

            if (!newQualifies) {
                continue;
            }

            if (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert) {
                tasksToInsert.add(buildTask(newOpp));
                continue;
            }

            // AfterUpdate: only create the task if it did NOT already qualify before.
            Opportunity oldOpp = (oldlist != null && oldlist.size() == newlist.size())
                ? (Opportunity) oldlist[i]
                : null;

            Boolean oldQualified = oldOpp != null
                && oldOpp.IsWon == true
                && oldOpp.Amount != null
                && oldOpp.Amount >= THRESHOLD_AMOUNT;

            if (!oldQualified) {
                tasksToInsert.add(buildTask(newOpp));
            }
        }

        if (!tasksToInsert.isEmpty()) {
            // Insert directly so the Tasks exist immediately after the handler runs,
            // regardless of whether the calling context processes the returned
            // DmlWrapper. This keeps the handler to exactly 1 DML statement of its own.
            insert tasksToInsert;
        }

        return dmlWrapper;
    }

    private Task buildTask(Opportunity opp) {
        Task t = new Task();
        t.Subject = MAJOR_GIFT_SUBJECT;
        t.Priority = 'High';
        t.Status = 'Not Started';
        t.WhatId = opp.Id;
        t.WhoId = opp.npsp__Primary_Contact__c;
        t.OwnerId = opp.OwnerId;
        t.ActivityDate = opp.CloseDate != null ? opp.CloseDate.addDays(3) : null;
        return t;
    }
}
