/**
 * Before-insert action for Contact: when a new contact has an Account and all four mailing
 * address fields (MailingStreet, MailingCity, MailingPostalCode, MailingCountry) are blank,
 * copies the corresponding Billing fields from the parent Account onto the contact.
 *
 * Relies on TA_Contact_Queries.Service having already populated the shared accountsById map
 * earlier in the same before insert context (lower Order__c), so this action performs no
 * SOQL of its own.
 */
public with sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;
        if (accountsById == null || accountsById.isEmpty()) {
            return;
        }

        for (SObject so : triggerNew) {
            Contact c = (Contact) so;

            if (c.AccountId == null) {
                continue;
            }

            Boolean mailingAddressBlank =
                String.isBlank(c.MailingStreet) &&
                String.isBlank(c.MailingCity) &&
                String.isBlank(c.MailingPostalCode) &&
                String.isBlank(c.MailingCountry);

            if (!mailingAddressBlank) {
                continue;
            }

            Account parentAccount = accountsById.get(c.AccountId);
            if (parentAccount == null) {
                continue;
            }

            c.MailingStreet = parentAccount.BillingStreet;
            c.MailingCity = parentAccount.BillingCity;
            c.MailingPostalCode = parentAccount.BillingPostalCode;
            c.MailingCountry = parentAccount.BillingCountry;
        }
    }
}
